}

.helper-text {
  font-size: 13px;
  color: #909090;
  line-height: 1.4;
}

.error-message {
  font-size: 13px;
  color: #ef4444;
  line-height: 1.4;
  min-height: 19px;
}

.error-message:empty {
  display: none;
}

.submit-button {
  padding: 12px 24px;
  background-color: #6366f1;
  color: #ffffff;
  font-size: 16px;
  font-weight: 500;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  transition: background-color 0.2s ease, box-shadow 0.2s ease;
  margin-top: 8px;
}

.submit-button:hover {
  background-color: #4f46e5;
}

.submit-button:focus {
  outline: none;
  background-color: #4f46e5;
  box-shadow: 0 0 0 3px rgba(99, 102, 241, 0.3);
}

.submit-button:active {
  background-color: #4338ca;
}

.submit-button:disabled {
  background-color: #4b5563;
